import csv
import io

_DECIMAL_DIGITS = set('0123456789')


def _clean(field):
    return field.strip() if isinstance(field, str) else ''


def import_text(text, store, dry_run=False):
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    pending = []

    for row in csv.DictReader(io.StringIO(text)):
        sku = _clean(row['sku'])
        name = _clean(row['name'])
        qty = _clean(row['qty'])
        if not sku:
            raise ValueError('empty sku')
        if not name:
            raise ValueError('empty name')
        if not qty or not all(c in _DECIMAL_DIGITS for c in qty):
            raise ValueError('invalid quantity')
        item = {'sku': sku, 'name': name, 'qty': int(qty)}

        before = store.get(sku)
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        pending.append({'sku': sku, 'before': before, 'after': item})

    if pending:
        result['changes'] = pending
        if not dry_run:
            for change in pending:
                store.put(change['after'])
    return result

